// ====================== src/main.js ======================
import { createApp } from 'vue'
import { createPinia } from 'pinia'
import App from './App.vue'
import router from './router'

const app = createApp(App)
app.use(createPinia())
app.use(router)
app.mount('#app')

// ====================== src/router/index.js ======================
import { createRouter, createWebHistory } from 'vue-router'
import Home from '../views/Home.vue'
import RecipeDetail from '../views/RecipeDetail.vue'
import About from '../views/About.vue'

const routes = [
  { path: '/', component: Home },
  { path: '/recipe/:id', component: RecipeDetail, props: true },
  { path: '/about', component: About }
]

export default createRouter({
  history: createWebHistory(),
  routes
})

// ====================== src/stores/favorites.js ======================
import { defineStore } from 'pinia'

export const useFavoritesStore = defineStore('favorites', {
  state: () => ({
    ids: []
  }),
  getters: {
    favorites: (state) => state.ids
  },
  actions: {
    toggle(id) {
      if (this.ids.includes(id)) {
        this.ids = this.ids.filter(i => i !== id)
      } else {
        this.ids.push(id)
      }
    }
  }
})

// ====================== src/composables/useFetch.js ======================
import { ref } from 'vue'

export function useFetch(url) {
  const data = ref(null)
  const loading = ref(false)
  const error = ref(null)

  const fetchData = async () => {
    loading.value = true
    try {
      const res = await fetch(url)
      if (!res.ok) throw new Error(res.statusText)
      data.value = await res.json()
    } catch (err) {
      error.value = err.message
    } finally {
      loading.value = false
    }
  }

  fetchData()
  return { data, loading, error, refetch: fetchData }
}

// ====================== src/composables/useLocalStorage.js ======================
import { ref, watch } from 'vue'

export function useLocalStorage(key, defaultValue) {
  const stored = localStorage.getItem(key)
  const data = ref(stored ? JSON.parse(stored) : defaultValue)
  watch(data, (val) => {
    localStorage.setItem(key, JSON.stringify(val))
  }, { deep: true })
  return data
}

// ====================== src/components/RecipeCard.vue ======================
<template>
  <div class="recipe-card" @click="goToDetail">
    <h3>{{ recipe.title }}</h3>
    <p>{{ recipe.description }}</p>
    <button @click.stop="toggleFavorite">
      {{ isFavorite ? '❤️' : '🤍' }}
    </button>
  </div>
</template>

<script setup>
import { useRouter } from 'vue-router'
import { useFavoritesStore } from '../stores/favorites'

const props = defineProps(['recipe'])
const router = useRouter()
const favoritesStore = useFavoritesStore()

const isFavorite = computed(() => favoritesStore.favorites.includes(props.recipe.id))

const goToDetail = () => {
  router.push(`/recipe/${props.recipe.id}`)
}

const toggleFavorite = () => {
  favoritesStore.toggle(props.recipe.id)
}
</script>

<style scoped>
.recipe-card {
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 16px;
  margin: 10px;
  cursor: pointer;
}
</style>

// ====================== src/views/Home.vue ======================
<template>
  <div>
    <h1>Recipes</h1>
    <div v-if="loading">Loading...</div>
    <div v-else-if="error">{{ error }}</div>
    <div v-else class="recipes-grid">
      <RecipeCard v-for="recipe in data" :key="recipe.id" :recipe="recipe" />
    </div>
  </div>
</template>

<script setup>
import { useFetch } from '../composables/useFetch'
import RecipeCard from '../components/RecipeCard.vue'

const { data, loading, error } = useFetch('https://jsonplaceholder.typicode.com/posts')
// Using JSONPlaceholder as mock recipe data
</script>

<style scoped>
.recipes-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
}
</style>

// ====================== src/views/RecipeDetail.vue ======================
<template>
  <div v-if="loading">Loading...</div>
  <div v-else-if="error">{{ error }}</div>
  <div v-else>
    <h2>{{ recipe.title }}</h2>
    <p>{{ recipe.body }}</p>
    <button @click="toggleFavorite">
      {{ isFavorite ? 'Remove from Favorites' : 'Add to Favorites' }}
    </button>
    <router-link to="/">Back</router-link>
  </div>
</template>

<script setup>
import { useRoute } from 'vue-router'
import { useFetch } from '../composables/useFetch'
import { useFavoritesStore } from '../stores/favorites'
import { computed } from 'vue'

const route = useRoute()
const { data: recipe, loading, error } = useFetch(`https://jsonplaceholder.typicode.com/posts/${route.params.id}`)
const favoritesStore = useFavoritesStore()

const isFavorite = computed(() => favoritesStore.favorites.includes(route.params.id))

const toggleFavorite = () => {
  favoritesStore.toggle(route.params.id)
}
</script>

