<template>
  <form @submit.prevent="submit">
    <div>
      <label for="name">Name</label>
      <input id="name" v-model="name" @blur="touched.name = true" />
      <span v-if="touched.name && !name">Name is required</span>
    </div>
    <div>
      <label for="email">Email</label>
      <input id="email" v-model="email" @blur="touched.email = true" />
      <span v-if="touched.email && !email.includes('@')">Valid email required</span>
    </div>
    <button type="submit" :disabled="!name || !email.includes('@')">Send</button>
  </form>
</template>

<script setup>
import { ref } from 'vue'

const name = ref('')
const email = ref('')
const touched = ref({ name: false, email: false })

const submit = () => {
  alert(`Thank you, ${name.value}!`)
  name.value = ''
  email.value = ''
  touched.value = { name: false, email: false }
}
</script>

